        product = __product,
        watermark = __watermark,
        delivery_marker = __marker,
        signals = {
            assembly_death_signals = {
                voodoo = {7.5, -3.25, 5.125},
                eggler = {-6.375, 4.875, -7.625},
                hexa = {5.875, -7.25, 3.625},
                plank = {-4.625, -6.875, 7.25},
                mace = {6.75, 5.625, -4.375},
                gummy = {-5.5, 7.125, 6.25},
                roguelike = {8.125, 4.375, -6.75},
                engineer = {-8.625, 6.375, 4.75},
                rage = {4.375, -5.625, 8.125},
                barrel = {-7.125, -5.375, 6.875},
            },
            assembly_mode_signals = {
                engineer_task13 = {3.875, 8.625, -6.125},
                engineer_task3 = {-4.125, -8.375, 6.625},
            },
            assembly_slap_signal = {-7.5, 3.25, -5.125},
        },
    }
    function __capability.claim(__value)
        if __claimed or __revoked or __value ~= __marker then return nil end
        __claimed = true
        return __hmac(__secret, table.concat({
            "delivery-v4", __marker, __product, __fingerprint,
        }, __separator))
    end
    function __capability.verify(__launch)
        local __attempts = __launch and 3 or 1
        for __attempt = 1, __attempts do
            local __response, __isFatal = __runtimeRequest("heartbeat", nil, false)
            if __response then return true end
            if __isFatal then return false end
            if __attempt < __attempts then task.wait(0.35 * __attempt) end
        end
        return false
    end
    function __capability.report(__kind, __payload)
        local __response = __runtimeRequest(tostring(__kind or "heartbeat"), __payload, false)
        return __response
    end
    function __capability.guard()
        if __revoked then return false end
        local __response = __runtimeRequest("guard", { event = 1 }, false)
        __revoked = true
        return __response ~= nil
    end
    function __capability.revoke(__reason, __kick)
        __revoked = true
        if __kick == true then __fail(__reason, true) end
    end
    function __capability.is_valid()
        return __activated and not __revoked and __verifiedAt > 0
    end

    local __run = loadstring(__plain)
    __plain = nil
    if type(__run) ~= "function" then __fail("Secure payload could not be loaded.") end
    task.spawn(function()
        local __failures = 0
        while task.wait(15) do
            if __revoked then return end
            if __capability.verify(false) then
                __failures = 0
            else
                __failures += 1
                if __revoked or __failures >= 8 then
                    __fail("Secure session could not be verified.")
                end
            end
        end
    end)
    local __ran, __error = pcall(__run, __capability)
    if not __ran then error(tostring(__error), 0) end
end
